export function locateGuideSection(mapId, eventIndex = 0) {
  const index = guideSections.findIndex(section => section.mapId === Number(mapId) &&
    Number(eventIndex) >= section.eventStart && Number(eventIndex) <= section.eventEnd);
  return index < 0 ? 0 : index;
}

const edb = (term, definition) => ({term, definition, source:'edb'});
const added = (term, definition) => ({term, definition, source:'supplement'});

